'use strict';

// APG eBay enrichment telemetry endpoint v1.4.
// The former catalogue-enrichment execution surface is intentionally disabled. It was useful
// during rollout evaluation, but a repository-visible run id is not an appropriate quota gate for
// ongoing Production enrichment. All real eBay product-image verification/discovery now runs
// through api/ebay-image-refresh.js using short-lived one-time capabilities generated by Postgres.
// This endpoint remains read-only so APG can inspect Developer Analytics quota without consuming
// ordinary Browse item/search calls.

const {products}=require('../data');
const ebay=require('../lib/ebay-browse-api-v1');

const VERSION='1.4';
const RUN_ID='apg-ebay-enrichment-v1';
const QUOTA_RESERVE=500;

function clean(value){return String(value==null?'':value).trim();}
async function browseQuota(){
  const payload=await ebay.getRateLimits({apiName:'browse',apiContext:'buy',timeoutMs:6000});
  return ebay.summariseRateLimits(payload,{apiName:'browse',apiContext:'buy'});
}
function ordinaryRows(quota){
  const rows=Array.isArray(quota&&quota.resources)?quota.resources:[];
  const exact=rows.filter(row=>/^buy\.browse$/i.test(clean(row&&row.resource)));
  return exact.length?exact:rows.filter(row=>!/item\.bulk/i.test(clean(row&&row.resource)));
}
function quotaPublic(quota){
  const ordinary=ordinaryRows(quota);
  const remaining=ordinary.map(row=>Number(row&&row.remaining)).filter(Number.isFinite);
  return {
    found:Boolean(quota&&quota.found),
    exhausted:Boolean(remaining.length&&Math.min(...remaining)<=0),
    lowestRemaining:remaining.length?Math.min(...remaining):null,
    resetAt:quota&&quota.resetAt||null,
    reserve:QUOTA_RESERVE,
    resources:ordinary.map(row=>({
      apiName:row.apiName,apiContext:row.apiContext,apiVersion:row.apiVersion,resource:row.resource,
      limit:row.limit,remaining:row.remaining,count:row.count,reset:row.reset,timeWindow:row.timeWindow
    }))
  };
}

module.exports=async function handler(req,res){
  res.setHeader('Cache-Control','no-store, max-age=0');
  res.setHeader('X-Robots-Tag','noindex, nofollow, noarchive');
  if(req.method!=='GET'){res.setHeader('Allow','GET');return res.status(405).json({ok:false,status:'method-not-allowed'});}
  if(process.env.VERCEL_ENV!=='production')return res.status(404).json({ok:false,status:'production-only'});
  if(clean(req.query&&req.query.run)!==RUN_ID)return res.status(404).json({ok:false,status:'not-found'});

  const format=clean(req.query&&req.query.format)||'disabled';
  if(format!=='quota'){
    return res.status(410).json({
      ok:false,
      status:'superseded-by-secure-image-worker',
      version:VERSION,
      totalProducts:products.length,
      message:'Catalogue enrichment is disabled on this legacy route. Use the capability-protected background image worker.'
    });
  }

  let quota;
  try{quota=await browseQuota();}
  catch(error){
    return res.status(502).json({
      ok:false,status:'quota-check-failed',version:VERSION,totalProducts:products.length,
      errorCode:error&&error.code?String(error.code):'EBAY_QUOTA_CHECK_FAILED',
      errorStatus:Number.isFinite(error&&error.status)?Number(error.status):null
    });
  }
  return res.status(200).json({ok:true,version:VERSION,totalProducts:products.length,quota:quotaPublic(quota)});
};
